    resources = o.get("resources", []) or []
    obstacles = o.get("obstacles", []) or []
    blocked = set()
    for p in obstacles:
        if isinstance(p, (list, tuple)) and len(p) >= 2:
            blocked.add((to_int(p[0]), to_int(p[1])))
        elif isinstance(p, dict):
            blocked.add((to_int(p.get("x", 0)), to_int(p.get("y", 0))))

    targets = []
    for p in resources:
        if isinstance(p, (list, tuple)) and len(p) >= 2:
            targets.append((to_int(p[0]), to_int(p[1])))
        elif isinstance(p, dict):
            targets.append((to_int(p.get("x", 0)), to_int(p.get("y", 0))))

