            tx, ty = nx + ax, ny + ay
            if legal(tx, ty):
                free += 1
        score += free * 2

        if w > 0:
            cx = (w - 1) / 2.0
            score -= abs(nx - cx) * 0.2
        if h > 0:
            cy = (h - 1) / 2.0
            score -= abs(ny - cy) * 0.2

        if dx == 0 and dy == 0:
            score -= 0.5

        if best_score is None or score > best_score or (score == best_score and (dx, dy) < tuple(best_move)):
            best_score = score
            best_move = [dx, dy]

    return best_move

